def table(frame):
 return '\n'.join(['| '+' | '.join(frame.columns)+' |','| '+' | '.join(['---']*len(frame.columns))+' |']+['| '+' | '.join(str(x) for x in row)+' |' for row in frame.itertuples(index=False,name=None)])
phase=[]
for keys,g in p.groupby(['trace','policy','phase','K'],sort=True):
 z=dict(Trace=keys[0],Policy=keys[1],Phase=f'{keys[2]*15}–{(keys[2]+1)*15}',K=keys[3],n=len(g))
 for metric,label in [('DMR_percent','DMR %'),('queue_mean_ms','Queue ms'),('service_mean_ms','Service ms'),('local_p95_ms','Local run-P95 ms')]:z[label]=f'{g[metric].mean():.3f} ± {g[metric].std(ddof=1):.3f}'
 phase.append(z)
